head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.filterGubun = "";
scwin.questNo;
scwin.vCurDate;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(main);
        $c.libRoundPanel.PanelToGroupBox(sub1);
        $c.cm.PanelToGroupBox(sub2);
        scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
        getQuestNo = $c.frame.path("../").fn_getQuestNo;
        scwin.questNo = getQuestNo();
        if (scwin.questNo !== "input") {
            await scwin.read();
            // fn_mkGubunCheck();
            if (js_market === "1" || js_market === "2") {
                panel_mkt_gubun.hide();
            } else {
                panel_mkt_gubun.show("");
            }
            for (i = 1; i <= dts_Ques.getRowCount(); i++) {
                if (dts_Ques.getCellData(i, "RESPNS_MANDTRY_YN") === "N") {

                    // ********************************************************************
                    // [WebSquare 전환 추가] 원본 소스와 비교 필요
                    //
                    // ********************************************************************

                    /*ORG SRC: dts_Ques.nameString(i, "INDEX_GBN1") = "N";*/
                    X = "N";
                }
            }
        } else {
            await scwin.setSaveHeader();
            scwin.setObjInit();
            if (js_market === "1" || js_market === "2") {
                panel_mkt_gubun.hide();
                dts_Quest.setCellData(1, "LD_MKT_TP_CD", js_market);
            } else {
                panel_mkt_gubun.show("");
                mkgubun.setValue("1");
            }
            // fn_mkGubunCheck();

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30322.onpageload" });
    }
};

