/**
 * @method
 * @name btn_sub1_lineadd_onclick
 * @description 「행삽입」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_sub1_lineadd_onclick = function() {
    try {
        // 질문내용 추가
        if (scwin.questNo !== "input") {
            dts_Ques.insertRow();
            quest_number.SetColumn("QUES_CONTN");
            quest_number.focus();
            const newQuesNO = Number(dts_Ques.getCellData(dts_Ques.getRowPosition() - 1, "QUES_NO")) + 1;
            dts_Ques.setCellData(dts_Ques.getRowPosition(), "QUES_NO", newQuesNO);
            chb_rsp_mndt_y.setDisabled(false);
            chb_rsp_mndt_n.setDisabled(false);
            chb_rsp_mndt_y.setValue(0);
            chb_rsp_mndt_n.setValue(0);
            ques_tp_cd.setDisabled(false);
            sub2_panel.hide();
            dts_Ques.uesUpdate;
        } else {
            dts_Ques.insertRow();
            quest_number.SetColumn("QUES_CONTN");
            quest_number.focus();
            dts_Ques.setCellData(dts_Ques.getRowPosition(), "QUES_NO", dts_Ques.getRowCount());
            chb_rsp_mndt_y.setDisabled(false);
            chb_rsp_mndt_n.setDisabled(false);
            chb_rsp_mndt_y.setValue(0);
            chb_rsp_mndt_n.setValue(0);
            ques_tp_cd.setDisabled(false);
            sub2_panel.hide();
            // if(dts_Ques.countRow == 1){
            //    dts_Ques.NameString(dts_Ques.RowPosition,"RESPNS_MANDTRY_YN") = "N";
            // }

        }
        scwin.initload();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30322.btn_sub1_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_sub1_linedelete_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sub1_linedelete_onclick = async function() {
    try {
        // 질문내용 삭제

        let ques_no = dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO");
        let rsp_mndt_check = "";
        for (i = 1; i <= dts_Ques.getRowCount(); i++) {
            if (ques_no === dts_Ques.getCellData(i, "UP_QUES_NO")) {
                rsp_mndt_check = "Y";
            }
        }
        if (rsp_mndt_check === "Y") {
            await $c.win.alert("상위 질문번호가 존재하여 삭제하실수 없습니다. 질문필수 \n선택을 필수아님으로 선택하신 후 다시 시도 하십시오.");
            return;
        }

        // 질문 후보값 삭제
        dts_Ques_Candidate_Val.setBroadcast(false);
        for (i = 1; i <= dts_Ques_Candidate_Val.getRowCount(); i++) {
            if (dts_Ques_Candidate_Val.getCellData(Number(i), "QUES_NO") === ques_no) {
                dts_Ques_Candidate_Val.removeRow(i - 1);
            }
        }
        dts_Ques_Candidate_Val.setBroadcast(true, true);
        // 주석값 삭제
        dts_Ques_Coment.setBroadcast(false);
        for (i = 1; i <= dts_Ques_Coment.getRowCount(); i++) {
            if (dts_Ques_Coment.getCellData(Number(i), "QUES_NO") === ques_no) {
                dts_Ques_Coment.removeRow(i - 1);
            }
        }
        dts_Ques_Coment.setBroadcast(true, true);
        if (scwin.questNo !== "input") {
            if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "INDEX_GBN") !== "") {
                dts_Ques.removeRow(dts_Ques.getRowPosition());
                let rtn = confirm('행삭제를 하시면 실제 내용이 삭제 됩니다.\n내용을 삭제 하시겠습니까?');
                if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

                {
                    // 행삭제시 별도로 질문내용및 후보값과 주석문을 같이 삭제한다.
                    const sbmOptions = {
                        id : "sbm_trs_Delete2",
                        action : "/QuestionMgt.do",
                        ref : "dts_Ques",
                        target : "trs_Delete2=body.content",
                        isProcessMsg : false
                    };

                    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
                }
                // fn_initFilter();

            } else {
                dts_Ques.removeRow(dts_Ques.getRowPosition());
                quest_number.SetColumn("QUES_CONTN");
                quest_number.focus();
            }
        } else {
            dts_Ques.removeRow(dts_Ques.getRowPosition());
            quest_number.SetColumn("QUES_CONTN");
            quest_number.focus();
        }
        if (dts_Ques.getRowCount() === 0) {
            scwin.setObjInit();
        }
        scwin.initload();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30322.btn_sub1_linedelete_onclick" });
    }
};

/**
 * @method
 * @name btn_sub2_lineadd1_onclick
 * @description 「행삽입」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_sub2_lineadd1_onclick = function() {
    try {
        // 질문후보값 추가
        if (dts_Ques.getRowCount() !== 0) {
            if (ques_tp_cd.getValue() !== "5") {
                dts_Ques_Candidate_Val.insertRow();
                grd_ques_candidate_val.SetColumn("QUES_CANDIDATE_VAL");
                grd_ques_candidate_val.focus();
                dts_Ques_Candidate_Val.setCellData(dts_Ques_Candidate_Val.getRowPosition(), "QUES_NO", dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO"));
                const newQuesValSeq = Number(dts_Ques_Candidate_Val.getCellData(dts_Ques_Candidate_Val.getRowPosition() - 1, "QUES_CANDIDATE_VAL_SEQ")) + 1;
                dts_Ques_Candidate_Val.setCellData(dts_Ques_Candidate_Val.getRowPosition(), "QUES_CANDIDATE_VAL_SEQ", newQuesValSeq);
                dts_Ques_Candidate_Val.setCellData(dts_Ques_Candidate_Val.getRowPosition(), "SEQ_NUM", dts_Ques_Candidate_Val.getRowCount());
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30322.btn_sub2_lineadd1_onclick" });
    }
};

/**
 * @method
 * @name btn_sub2_linedelete1_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sub2_linedelete1_onclick = async function() {
    try {
        // 질문후보값 삭제

        // 응답필수번호 리스트 체크
        // 질문번호
        const delQuesNo = dts_Ques_Candidate_Val.getCellData(dts_Ques_Candidate_Val.getRowPosition(), "QUES_NO");
        const delSeqNum = dts_Ques_Candidate_Val.getCellData(dts_Ques_Candidate_Val.getRowPosition(), "SEQ_NUM");

        // 응답필수번호리스트
        let upQuesNoValYn = "";
        for (i = 1; i <= dts_Ques.getRowCount(); i++) {
            if (dts_Ques.getCellData(i, "UP_QUES_NO") === delQuesNo) {
                let mndt_nos = dts_Ques.getCellData(i, "RESPNS_MANDTRY_NO").split(',');
                for (j = 0; j < mndt_nos.length; j++) {
                    if (mndt_nos[j] === delSeqNum) {
                        upQuesNoValYn = "Y";
                    }
                }
            }
        }
        if (upQuesNoValYn === "Y") {
            await $c.win.alert("삭제 하려하시는 답변값을 응답필수 답변번호로 쓰고있는 질문이 있습니다.\n 확인 후 다시 시도해주세요.");
            return;
        }
        if (scwin.questNo !== "input") {
            if (dts_Ques_Candidate_Val.getCellData(dts_Ques_Candidate_Val.getRowPosition(), "INDEX_GBN") !== "") {
                dts_Ques_Candidate_Val.removeRow(dts_Ques_Candidate_Val.getRowPosition());
                let rtn = confirm('행삭제를 하시면 실제 내용이 삭제 됩니다.\n내용을 삭제 하시겠습니까?');
                if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

                {
                    // 행삭제시 별도로 질문내용및 후보값과 주석문을 같이 삭제한다.
                    const sbmOptions = {
                        id : "sbm_trs_Delete2",
                        action : "/QuestionMgt.do",
                        ref : "dts_Ques_Candidate_Val",
                        target : "trs_Delete2=body.content",
                        isProcessMsg : false
                    };

                    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
                    scwin.initFilter();
                }
            } else {
                dts_Ques_Candidate_Val.removeRow(dts_Ques_Candidate_Val.getRowPosition());
                grd_ques_candidate_val.SetColumn("QUES_CANDIDATE_VAL");
                grd_ques_candidate_val.focus();
            }
        } else {
            dts_Ques_Candidate_Val.removeRow(dts_Ques_Candidate_Val.getRowPosition());
            grd_ques_candidate_val.SetColumn("QUES_CANDIDATE_VAL");
            grd_ques_candidate_val.focus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30322.btn_sub2_linedelete1_onclick" });
    }
};

/**
 * @method
 * @name btn_sub2_lineadd2_onclick
 * @description 「행삽입」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_sub2_lineadd2_onclick = function() {
    try {
        // 주석값 추가
        if (dts_Ques.getRowCount() !== 0) {
            dts_Ques_Coment.insertRow();
            grd_coment_val.focus();
            dts_Ques_Coment.setCellData(dts_Ques_Coment.getRowPosition(), "QUES_NO", dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO"));
            const newQuesComSeq = Number(dts_Ques_Coment.getCellData(dts_Ques_Coment.getRowPosition() - 1, "QUES_COMENT_SEQ")) + 1;
            dts_Ques_Coment.setCellData(dts_Ques_Coment.getRowPosition(), "QUES_COMENT_SEQ", newQuesComSeq);
            dts_Ques_Coment.setCellData(dts_Ques_Coment.getRowPosition(), "CHAR_SZ", "1");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30322.btn_sub2_lineadd2_onclick" });
    }
};

/**
 * @method
 * @name btn_sub2_linedelete2_onclick
 * @description 「행삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sub2_linedelete2_onclick = async function() {
    try {
        // 주석값 삭제
        if (scwin.questNo !== "input") {
            if (dts_Ques_Coment.getCellData(dts_Ques_Coment.getRowPosition(), "INDEX_GBN") !== "") {
                // 행삭제시 별도로 질문내용및 후보값과 주석문을 같이 삭제한다.
                let rtn = confirm('행삭제를 하시면 실제 내용이 삭제 됩니다.\n내용을 삭제 하시겠습니까?');
                if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

                {
                    dts_Ques_Coment.removeRow(dts_Ques_Coment.getRowPosition());
                    const sbmOptions = {
                        id : "sbm_trs_Delete2",
                        action : "/QuestionMgt.do",
                        ref : "dts_Ques_Coment",
                        target : "trs_Delete2=body.content",
                        isProcessMsg : false
                    };

                    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
                    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
                    scwin.initFilter();
                }
            } else {
                dts_Ques_Coment.removeRow(dts_Ques_Coment.getRowPosition());
                grd_coment_val.focus();
            }
        } else {
            dts_Ques_Coment.removeRow(dts_Ques_Coment.getRowPosition());
            grd_coment_val.focus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30322.btn_sub2_linedelete2_onclick" });
    }
};

