/**
 * @method
 * @name dts_Ques_Candidate_Val_OnFilter
 * @description Ques Candidate Val On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_Ques_Candidate_Val_OnFilter = function(row) {
    try {
        // 질문 후보값 그리드 내용 필터링 이벤트
        switch (scwin.filterGubun) {
            case "1":
                return true;
                break;
            case "2":
                let sub1 = dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO");
                let sub2_1 = dts_Ques_Candidate_Val.getCellData(row, "QUES_NO");
                if (sub1 === sub2_1) return true;

                else return false;
                return;
                break;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30322.dts_Ques_Candidate_Val_OnFilter" });
    }
};

/**
 * @method
