};

/**
 * @method
 * @name chb_rsp_mndt_y_onclick
 * @description chb_rsp_mndt_y 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chb_rsp_mndt_y_onclick = function() {
    try {
        // 종속필수 컨트롤
        if (dts_Ques.getRowCount() !== 0) {
            if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO") === "1") {
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "Y");
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "INDEX_GBN1", "");
                sub2_panel.hide();
                chb_rsp_mndt_y.setDisabled(true);
                chb_rsp_mndt_y.setValue(0);
                return;
            } else {
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "Y");
                if (chb_rsp_mndt_y.checked === true) {
                    sub2_panel.show("");
                    chb_rsp_mndt_n.setDisabled("enable");
                } else {
                    dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "Y");
                    dts_Ques.setCellData(dts_Ques.getRowPosition(), "INDEX_GBN1", "");
                    dts_Ques.setCellData(dts_Ques.getRowPosition(), "UP_QUES_NO", "0");
                    dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_NO", "");
                    sub2_panel.hide();
                    chb_rsp_mndt_n.setDisabled(false);
                }
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30322.chb_rsp_mndt_y_onclick" });
    }
};

/**
 * @method
 * @name chb_rsp_mndt_n_onclick
 * @description chb_rsp_mndt_n 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.chb_rsp_mndt_n_onclick = function() {
    try {
        // 종속 필수 아님 컨트롤
        if (dts_Ques.getRowCount() !== 0) {
            /*
            		if(dts_Ques.NameString(dts_Ques.RowPosition,"QUES_NO") == "1"){
            			chb_rsp_mndt_n.checked = true;
            			chb_rsp_mndt_y.checked = false;
            			return;
            		}
             */

            if (chb_rsp_mndt_n.checked === true) {
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "N");
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "INDEX_GBN1", "N");
                tbox_up_ques_no.setValue("0");
                tbox_rsp_mndt_no.setValue("");
                chb_rsp_mndt_y.setDisabled("enable");
            } else {
                chb_rsp_mndt_y.setDisabled(false);
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN", "Y");
                dts_Ques.setCellData(dts_Ques.getRowPosition(), "INDEX_GBN1", "");
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30322.chb_rsp_mndt_n_onclick" });
    }
};

/**
 * @method
 * @name ques_tp_cd_onselchange
 * @description ques_tp_cd onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.ques_tp_cd_onselchange = function() {
    try {
        // 질문유형 이벤트
        if (ques_tp_cd.getValue() === "1" || ques_tp_cd.getValue() === "4" || ques_tp_cd.getValue() === "5") {
            tbox_ans_choic_cnt.setValue("");
            tbox_ans_choic_cnt.setReadOnly(true);
            tbox_ans_choic_cnt.style.backgroundColor = "b9d4f7"; // .background-color = "#b9d4f7";
            // 질문 그리드 컨트롤 주관식으로 수정할경우
            if (ques_tp_cd.getValue() === "5") {
                let ques_no = dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_NO");
                dts_Ques_Candidate_Val.setBroadcast(false);
                for (i = 1; i <= dts_Ques_Candidate_Val.getRowCount(); i++) {
                    if (dts_Ques_Candidate_Val.getCellData(Number(i), "QUES_NO") === ques_no) {
                        dts_Ques_Candidate_Val.removeRow(i - 1);
                    }
                }
                dts_Ques_Candidate_Val.setBroadcast(true, true);
                grd_ques_candidate_val.setDisabled(true);
                grd_ques_candidate_val.setDisabled(true);
            } else {
                grd_ques_candidate_val.setDisabled(false);
                grd_ques_candidate_val.setDisabled(false);
            }
        } else {
            tbox_ans_choic_cnt.setValue("");
            tbox_ans_choic_cnt.setReadOnly(false);
            grd_ques_candidate_val.setDisabled(false);
            tbox_ans_choic_cnt.style.backgroundColor = "FFFFFF";
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30322.ques_tp_cd_onselchange" });
    }
};

