/**
 * @method
 * @name save
 * @description 설문등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    // 설문등록
    // if(tbox_quest_title.value == "" || tbox_quest_title.value.indexOf(" ") == "" ){//설문제목 체크
    if (tbox_quest_title.getValue() === "") {
        // 설문제목 체크
        await $c.win.alert("[설문 제목]을 입력하세요");
        return;
    }
    if (!await scwin.checkMaxLength1(tbox_quest_title, 1000, "설문 제목")) {
        tbox_quest_title.setValue("");
        tbox_quest_title.focus();
        return false;
    }
    if (edt_SDate.getValue() === "" || edt_SDate.Text.indexOf(" ") === "") {
        // 설문시작일 체크
        await $c.win.alert("[설문 시작일]을 선택하세요.");
        return;
    }
    if (edt_EDate.getValue() === "" || edt_EDate.Text.indexOf(" ") === "") {
        // 설문종료일 체크
        await $c.win.alert("[설문 종료일]을 선택하세요.");
        return;
    }
    if (await scwin.dateCheck() === false) {
        return;
    }
    if (mkgubun.getValue() === "") {
        await $c.win.alert("[설문대상 시장]을 선택하세요.");
        return;
    }
    if (dts_Ques.getRowCount() === 0) {
        await $c.win.alert("[질문]을 입력하세요");
        return;
    }
    if (await scwin.Validate() === false) {
        return;
    }
    dts_Ques_Candidate_Val.UseFilter = true;
    scwin.filterGubun = "1";
    dts_Ques_Candidate_Val.Filter();
    dts_Ques_Coment.UseFilter = true;
    scwin.filterGubun = "1";
    dts_Ques_Coment.Filter();
    let index = 1;
    // 질문후보값 SEQ 세팅
    let ques_no = dts_Ques_Candidate_Val.getCellData(1, "QUES_NO");
    dts_Ques_Candidate_Val.setBroadcast(false);
    for (i = 1; i <= dts_Ques_Candidate_Val.getRowCount(); i++) {
        if (ques_no !== dts_Ques_Candidate_Val.getCellData(i, "QUES_NO")) {
            ques_no = dts_Ques_Candidate_Val.getCellData(i, "QUES_NO");
            index = 1;
        }
        dts_Ques_Candidate_Val.setCellData(i, "QUES_CANDIDATE_VAL_SEQ", index);
        index++;
    }
    dts_Ques_Candidate_Val.setBroadcast(true, true);

    // 주석문 SEQ 세팅
    index = 1;
    ques_no = dts_Ques_Coment.getCellData(1, "QUES_NO");
    dts_Ques_Coment.setBroadcast(false);
    for (i = 1; i <= dts_Ques_Coment.getRowCount(); i++) {
        if (ques_no !== dts_Ques_Coment.getCellData(i, "QUES_NO")) {
            ques_no = dts_Ques_Coment.getCellData(i, "QUES_NO");
            index = 1;
        }
        dts_Ques_Coment.setCellData(i, "QUES_COMENT_SEQ", index);
        index++;
    }
    dts_Ques_Coment.setBroadcast(true, true);

    // 응답필수리스트 1자리숫자앞에 '0' 채워주기
    dts_Ques.setBroadcast(false);
    for (i = 1; i <= dts_Ques.getRowCount(); i++) {
        if (dts_Ques.getCellData(i, "RESPNS_MANDTRY_NO") !== "") {
            let mndt_nos = dts_Ques.getCellData(i, "RESPNS_MANDTRY_NO").split(',');
            let mndt_no = "";
            for (j = 0; j < mndt_nos.length; j++) {
                if (mndt_nos[j].length === 1) {
                    mndt_nos[j] = '0' + mndt_nos[j];
                }
                if (j > 0) {
                    mndt_nos[j] = ',' + mndt_nos[j];
                }
                mndt_no += mndt_nos[j];
            }
            dts_Ques.setCellData(i, "RESPNS_MANDTRY_NO", mndt_no);
        }
    }
    dts_Ques.setBroadcast(true, true);
    let rtn = confirm('내용을 등록 하시겠습니까?');
    if (rtn === 1) // [확인] 버튼이 눌려졌을 경우

    {
        dts_Ques.setBroadcast(false);
        for (i = 1; i <= dts_Ques.getRowCount(); i++) {
            if (dts_Ques.getCellData(i, "UP_QUES_NO") === "0" && dts_Ques.getCellData(i, "INDEX_GBN1") !== "N") {
                dts_Ques.setCellData(i, "RESPNS_MANDTRY_YN", "Y");
            }
        }
        dts_Ques.setBroadcast(true, true);
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/QuestionMgt.do",
            ref : "dts_Quest,dts_Ques,dts_Ques_Candidate_Val,dts_Ques_Coment",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

