/**
 * @method
 * @name initload
 * @description initload 처리
 * @returns {void}
 * @hidden N
 */
scwin.initload = function() {
    if (ques_tp_cd.getValue() !== "2") {
        grd_ques_candidate_val.setDisabled(false);
        grd_ques_candidate_val.setDisabled(false);
    }

    // 질문후보값, 주석값 필터링
    dts_Ques_Candidate_Val.UseFilter = true;
    scwin.filterGubun = "2";
    dts_Ques_Candidate_Val.Filter();
    dts_Ques_Coment.UseFilter = true;
    dts_Ques_Coment.Filter();
    tbox_ques_no.setValue(dts_Ques.getRowPosition());
    tbox_ans_choic_cnt.style.backgroundColor = "FFFFFF";
    scwin.mandtryYn();
    // 선택개수입력 컨트롤

    if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_TP_CD") === "1" ||
        dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_TP_CD") === "4" ||
        dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_TP_CD") === "5") {
        tbox_ans_choic_cnt.setValue("");
        tbox_ans_choic_cnt.setReadOnly(true);
        tbox_ans_choic_cnt.style.backgroundColor = "b9d4f7";
    } else if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "QUES_TP_CD") === "") {
        tbox_ans_choic_cnt.setValue("");
        tbox_ans_choic_cnt.setReadOnly(true);
    } else {
        if (tbox_ans_choic_cnt.getValue() === "0") {
            tbox_ans_choic_cnt.setValue("");
        }
        tbox_ans_choic_cnt.setReadOnly(false);
        tbox_ans_choic_cnt.style.backgroundColor = "FFFFFF";
    }
};

/**
 * @method
 * @name mandtryYn
 * @description 질문 필수선택 컨트롤
 * @returns {void}
 * @hidden N
 */
scwin.mandtryYn = function() {
    // 질문 필수선택 컨트롤
    if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN") === "Y") {
        if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "UP_QUES_NO") !== "0") {
            sub2_panel.show("");
            chb_rsp_mndt_y.setValue(1);
            chb_rsp_mndt_n.setValue(0);
            chb_rsp_mndt_y.setDisabled(false);
            chb_rsp_mndt_n.setDisabled(true);
        } else {
            sub2_panel.hide();
            chb_rsp_mndt_y.setValue(0);
            chb_rsp_mndt_y.setDisabled(false);
            chb_rsp_mndt_n.setValue(0);
            chb_rsp_mndt_n.setDisabled(false);
        }
    } else if (dts_Ques.getCellData(dts_Ques.getRowPosition(), "RESPNS_MANDTRY_YN") === "N") {
        sub2_panel.hide();
        chb_rsp_mndt_y.setValue(0);
        chb_rsp_mndt_y.setDisabled(true);
        chb_rsp_mndt_n.setValue(1);
        chb_rsp_mndt_n.setDisabled(false);
    } else {
        sub2_panel.hide();
        chb_rsp_mndt_y.setValue(0);
        chb_rsp_mndt_y.setDisabled(false);
        chb_rsp_mndt_n.setValue(0);
        chb_rsp_mndt_n.setDisabled(false);
    }
};

/**
 * @method
 * @name isNumber
 * @description is Number 처리
 * @param {*} inputVal inputVal
 * @returns {void}
 * @hidden N
 */
scwin.isNumber = function(inputVal) {
    oneDecimal = false;
    const inputStr = inputVal.toString();
    let oneChar;
    for (let i = 0; i < inputStr.length; i++) {
        oneChar = inputStr.charAt(i);
        if (i === 0 && oneChar === "-") {
            continue;
        }
        if (oneChar === "." && !oneDecimal) {
            oneDecimal = true;
            continue;
        }
        if (oneChar < "0" || oneChar > "9") {
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name validCheck
 * @description 질문제목 체크
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validCheck = async function(obj) {
    // 질문제목 체크
    if (dts_Ques.getCellData(obj, "QUES_CONTN") === "") {
        await $c.win.alert("[" + obj + "번째 질문 제목]을 입력하세요");
        return false;
    }
    // 질문 유형 체크
    if (dts_Ques.getCellData(obj, "QUES_TP_CD") === "") {
        await $c.win.alert("[" + obj + "번째 질문 유형]을 입력하세요");
        return false;
    }
    // 객관식 질문의 후보값 체크 -> 질문유형이 주관식이 아닐경우
    if (dts_Ques.getCellData(obj, "QUES_TP_CD") !== "5") {
        if (scwin.questNo !== "input") {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "1";
            dts_Ques_Candidate_Val.Filter();
            let checkVal = "";
            for (i = 1; i <= dts_Ques_Candidate_Val.getRowCount(); i++) {
                if (dts_Ques.getCellData(obj, "QUES_NO") === dts_Ques_Candidate_Val.getCellData(i, "QUES_NO")) {
                    checkVal = "Y";
                }
            }
            if (checkVal !== "Y") {
                dts_Ques_Candidate_Val.UseFilter = true;
                scwin.filterGubun = "2";
                dts_Ques_Candidate_Val.Filter();
                await $c.win.alert("[" + obj + "번째 질문후보값]을 입력하세요");
                return false;
            }
        } else {
            if (dts_Ques_Candidate_Val.getRowCount() < 1) {
                await $c.win.alert("[" + obj + "번째 질문답변값]을 입력하세요");
                return false;
            } else {
                let ques_value_check = "";
                for (i = 1; i <= dts_Ques_Candidate_Val.getRowCount(); i++) {
                    // 질문후보값 체크
                    if (dts_Ques_Candidate_Val.getCellData(i, "QUES_CANDIDATE_VAL") === "") {
                        ques_value_check = ques_value_check + i + ",";
                    }
                }
                if (ques_value_check !== "") {
                    await $c.win.alert("[" + obj + "번째 질문]에 " + "[" + ques_value_check + "번째 답변값]을 입력하세요");
                    return false;
                }
            }
        }
    }
    if (dts_Ques.getCellData(obj, "QUES_TP_CD") === "2" || dts_Ques.getCellData(obj, "QUES_TP_CD") === "3") {
        if (dts_Ques.getCellData(obj, "ANS_CHOIC_CNT") === "" || dts_Ques.getCellData(obj, "ANS_CHOIC_CNT") === "0" || dts_Ques.getCellData(obj, "ANS_CHOIC_CNT").indexOf(" ") === "") {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "2";
            dts_Ques_Candidate_Val.Filter();
            await $c.win.alert("[" + obj + "번째 질문의 선택갯수]를 입력해주세요.");
            return false;
        }
        if (!$c.cm.isNumber(dts_Ques.getCellData(obj, "ANS_CHOIC_CNT"))) {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "2";
            dts_Ques_Candidate_Val.Filter();
            await $c.win.alert("[" + obj + "번째 질문의 선택갯수]를 숫자로 입력해주세요.");
            return false;
        }
        if (Number(dts_Ques.getCellData(obj, "ANS_CHOIC_CNT")) > dts_Ques_Candidate_Val.getRowCount()) {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "2";
            dts_Ques_Candidate_Val.Filter();
            await $c.win.alert("[" + obj + "번째 질문의 선택개수 또는 후보값 개수]가 바르지 않습니다.");
            return false;
        }
    }
    if (dts_Ques.getCellData(obj, "RESPNS_MANDTRY_YN") === "Y") {
        if (!$c.cm.isNumber(dts_Ques.getCellData(obj, "UP_QUES_NO"))) {
            dts_Ques_Candidate_Val.UseFilter = true;
            scwin.filterGubun = "2";
            dts_Ques_Candidate_Val.Filter();
            await $c.win.alert("[" + obj + "번째 질문의 상위질문번호]를 숫자로 입력해주세요.");
            return false;
        }
        // 상위질문번호가 있는지 검사.
        if (dts_Ques.getCellData(obj, "UP_QUES_NO") !== "0") {
            let upQuesNoYn = "";
            for (i = 1; i <= dts_Ques.getRowCount(); i++) {
                if (dts_Ques.getCellData(i, "QUES_NO") === dts_Ques.getCellData(obj, "UP_QUES_NO")) {
                    upQuesNoYn = "Y";
                }
            }
            if (upQuesNoYn !== "Y") {
                dts_Ques_Candidate_Val.UseFilter = true;
                scwin.filterGubun = "2";
                dts_Ques_Candidate_Val.Filter();
                await $c.win.alert("[" + obj + "번째 질문의 상위질문번호]가 없습니다.");
                return false;
            }
        }
    }
    for (i = 1; i <= obj - 1; i++) {
        if (dts_Ques.getCellData(i, "QUES_NO") === dts_Ques.getCellData(obj, "UP_QUES_NO")) {
            if (dts_Ques.getCellData(i, "QUES_TP_CD") !== "5") {
                if (dts_Ques.getCellData(obj, "RESPNS_MANDTRY_NO") === "" ||
                    dts_Ques.getCellData(obj, "RESPNS_MANDTRY_NO") === "0" ||
                    dts_Ques.getCellData(obj, "RESPNS_MANDTRY_NO").indexOf(" ") === "") {
                    dts_Ques_Candidate_Val.UseFilter = true;
                    scwin.filterGubun = "2";
                    dts_Ques_Candidate_Val.Filter();
                    await $c.win.alert("[" + obj + "번째 질문의 상위 질문에 대한 응답필수 답변번호]를 입력하세요.");
                    return false;
                }
            }
        }
    }
    if (scwin.questNo !== "input") {
        dts_Ques_Candidate_Val.UseFilter = true;
        scwin.filterGubun = "2";
        dts_Ques_Candidate_Val.Filter();
    }
    return true;
};

/**
 * @method
 * @name Validate
 * @description Validate 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.Validate = async function() {
    for (let i = 1; i <= dts_Ques.getRowCount(); i++) {
        if (await scwin.validCheck(i) === false) return false;
    }
};

/**
